var update = flag.Bool("update", false, "rewrite golden files")

func TestLegacyQuote(t *testing.T) {
    got := runQuote(t, "A-1", 2)
    path := filepath.Join("testdata", "quote_A-1.txt")
    if *update {
        if err := os.WriteFile(path, got, 0o644); err != nil {
            t.Fatal(err)
        }
    }
    want, err := os.ReadFile(path)
    if err != nil {
        t.Fatal(err)                    // a missing golden is a failure, never a recording
    }
    if !bytes.Equal(want, got) {
        t.Errorf("golden mismatch; rerun with -update after review")
    }
}

